    wire = if val, do: <<14, 4>>, else: <<10, 4>>

    dirty_wire =
      op.dirty_wire
      |> Map.put(14, [])
      |> Map.put(15, [])
      |> Map.put(17, [])
      |> Map.put(16, wire)

    %{
      op
      | dirty_values: Map.put(op.dirty_values, {:oneof, :choice}, {:choice_flag, val}),
        dirty_wire: dirty_wire
    }
  end

  def set_choice(
        %__MODULE__{} = op,
        {:choice_child, %{__struct__: Omnibuf.Conformance.Editions2024Child} = val}
      ) do
    wire = [
      <<114, 4>>,
      OmniBuf.Wire.encode_length_prefixed(
        Omnibuf.Conformance.Editions2024Child.encode_iodata(val)
      )
    ]

    dirty_wire =
      op.dirty_wire
      |> Map.put(14, [])
      |> Map.put(15, [])
      |> Map.put(16, [])
      |> Map.put(17, wire)

    %{
      op
      | dirty_values: Map.put(op.dirty_values, {:oneof, :choice}, {:choice_child, val}),
        dirty_wire: dirty_wire
    }
  end
end
